# Start the DPDP RAG server on this PC with auth for public exposure.
#   powershell -File scripts\start_pc_stack.ps1
#
# Auth credentials come from .env (DPDP_USER, DPDP_AUTH_SALT, DPDP_AUTH_HASH --
# generated by scripts\hash_auth.py; the plaintext password is never stored).
# Any DPDP_* key in .env is exported to the server process.
param()

$root = Split-Path $PSScriptRoot -Parent
$envFile = Join-Path $root ".env"

if (-not (Test-Path $envFile)) {
    Write-Host "No .env found -- run scripts\hash_auth.py first to create credentials."
    exit 1
}
foreach ($line in Get-Content $envFile) {
    if ($line -match '^\s*([A-Z0-9_]+)\s*=\s*(.+?)\s*$' -and $Matches[1] -like 'DPDP_*') {
        [Environment]::SetEnvironmentVariable($Matches[1], $Matches[2], 'Process')
    }
}
if (-not $env:DPDP_USER) { Write-Host ".env has no DPDP_USER -- run scripts\hash_auth.py"; exit 1 }
Write-Host "auth enabled for user: $env:DPDP_USER"

# free the port
Get-NetTCPConnection -LocalPort 8000 -State Listen -ErrorAction SilentlyContinue |
    ForEach-Object { Stop-Process -Id $_.OwningProcess -Force }
Start-Sleep 2

Start-Process -FilePath "C:\Users\Hari\scoop\apps\python\current\python.exe" `
    -ArgumentList "-m","uvicorn","dpdp_rag.server:app","--app-dir",$root,`
                  "--host","0.0.0.0","--port","8000" -WindowStyle Hidden

Start-Sleep 6
try {
    $h = Invoke-RestMethod http://127.0.0.1:8000/health
    Write-Host "server up: $($h.status)"
    $a = Invoke-RestMethod http://127.0.0.1:8000/auth/check
    Write-Host "auth: required=$($a.auth_required)"
} catch { Write-Host "server FAILED: $($_.Exception.Message)"; exit 1 }
